package com.loanportal.model;

import io.quarkus.hibernate.orm.panache.PanacheEntityBase;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;

/**
 * Base entity using database IDENTITY columns (matches the Flyway-managed
 * "GENERATED BY DEFAULT AS IDENTITY" schema) instead of Panache's default
 * sequence-per-entity id strategy.
 */
@MappedSuperclass
public abstract class LoanPortalEntity extends PanacheEntityBase {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    public Long id;
}
